def _assess_measurements(
    measurements: list, bound: float, minimum: int
) -> "RangeDecision":
    """The robust inlier decision over already-validated measurements."""
    if len(measurements) < minimum:
        raise ValueError(f"need at least {minimum} samples, got {len(measurements)}")

    distances = _assess_distances(measurements)
    _center, _mad, inliers = _assess_inliers(distances)

    if len(inliers) < minimum:
        raise ValueError(
            f"need at least {minimum} inliers, got {len(inliers)}"
        )

    upper_bound = max(inliers)
    return RangeDecision(
        sample_count=len(measurements),
        upper_bound=upper_bound,
        accepted=upper_bound <= bound,
    )


def _assess_confidence_measurements(
    measurements: list, bound: float, minimum: int, level: float
) -> "NoiseDecision":
    """The coverage-bracketed robust decision over validated measurements."""
    if len(measurements) < minimum:
        raise ValueError(f"need at least {minimum} samples, got {len(measurements)}")

    distances = _assess_distances(measurements)
    center, mad, inliers = _assess_inliers(distances)

    count = len(inliers)
    if count < minimum:
        raise ValueError(
            f"need at least {minimum} inliers, got {count}"
        )

    ordered = sorted(inliers)
    alpha = 1.0 - level
    lower_rank = max(1, math.ceil(alpha * count / 2.0))
    upper_rank = min(count, math.ceil((1.0 - alpha / 2.0) * count))
    lower_bound = ordered[lower_rank - 1]
    upper_bound = ordered[upper_rank - 1]
    return NoiseDecision(
        sample_count=len(measurements),
        inlier_count=count,
        center=center,
        mad=mad,
        coverage=level,
        lower_bound=lower_bound,
        upper_bound=upper_bound,
        accepted=upper_bound <= bound,
    )


def _check_unit_interval(value: object, name: str) -> float:
    """Validate a non-bool finite number strictly between ``0`` and ``1``."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(
            f"{name} must be a finite number strictly between 0 and 1"
        )
    number = float(value)
    if not math.isfinite(number) or not 0.0 < number < 1.0:
        raise ValueError(
            f"{name} must be a finite number strictly between 0 and 1"
        )
    return number


def _clopper_pearson_upper(k: int, n: int, confidence: float) -> float:
    """One-sided Clopper-Pearson upper bound for a binomial probability.

    Returns the unique ``p`` in ``(0, 1)`` with
    ``sum(comb(n, j) * p**j * (1-p)**(n-j), j=0..k) == 1 - confidence``
    for ``X ~ Binomial(n, p)``; ``1.0`` when ``k == n``. The binomial CDF
    is strictly decreasing in ``p`` from ``1`` to ``0`` over ``(0, 1)``,
    so bisection converges to the unique root; the log-binomial
    coefficients are computed once via ``math.lgamma`` and each CDF
    evaluation sums the probability terms with ``math.fsum``, keeping the
    result within a few ulps of the exact bound.
    """
    if k == n:
        return 1.0
    alpha = 1.0 - confidence
    log_comb = [
        math.lgamma(n + 1) - math.lgamma(j + 1) - math.lgamma(n - j + 1)
        for j in range(k + 1)
    ]

    def cdf(p: float) -> float:
        log_p = math.log(p)
        log_q = math.log1p(-p)
        return math.fsum(
            math.exp(lc + j * log_p + (n - j) * log_q)
            for j, lc in enumerate(log_comb)
        )

    low, high = 0.0, 1.0
    while True:
        mid = (low + high) / 2.0
        if mid == low or mid == high:
            # Adjacent floats: the root is pinned to machine resolution.
            return mid
        if cdf(mid) > alpha:
            low = mid
        else:
            high = mid

